function mouse_move_2268a130950cdfc7bc21de8ae4e805032b9d4f36415af578982cc221bd21d91a520aafe2e5e206191775f15e6e1f111c9b0fcccf4e06b4577ad57a73788d7486(evt) {
    if (evt.buttons > 0) {
          var root = document.getElementById('2268a130950cdfc7bc21de8ae4e805032b9d4f36415af578982cc221bd21d91a520aafe2e5e206191775f15e6e1f111c9b0fcccf4e06b4577ad57a73788d7486');
          root.pauseAnimations();
          var new_time = 3 * evt.layerX / evt.target.getBBox().width;
          root.setCurrentTime(new_time);
    }
}
function on_click_2268a130950cdfc7bc21de8ae4e805032b9d4f36415af578982cc221bd21d91a520aafe2e5e206191775f15e6e1f111c9b0fcccf4e06b4577ad57a73788d7486(evt) {
